local BeginnerAssembleWelfareCell = Class("BeginnerAssembleWelfareCell")

function BeginnerAssembleWelfareCell:__init()
	self.btnActionJump = nil
	self.btnActionGet  = nil
end

function BeginnerAssembleWelfareCell:__delete()
	self.btnActionJump = nil
	self.btnActionGet  = nil
	self.controller    = nil
end

---SetBtnCallBackJump
---设置单击回调函数(跳转)
function BeginnerAssembleWelfareCell:SetBtnCallBackJump(cb)
	self.btnActionJump = cb
end

---SetBtnCallBackGet
---设置单击回调函数(领取)
function BeginnerAssembleWelfareCell:SetBtnCallBackGet(cb)
	self.btnActionGet = cb
end

function BeginnerAssembleWelfareCell:GetCellDt()
	return checkTable(self.cellDt)
end

function BeginnerAssembleWelfareCell:IsHasDrawn()
	return checkInt(self:GetCellDt().hasDrawn) == 1
end

function BeginnerAssembleWelfareCell:IsCanJump()
	return checkInt(self:GetCellDt().openType) ~= 0
end

function BeginnerAssembleWelfareCell:IsCanDrawn()
	return (checkNumber(self:GetCellDt().progress) >= checkNumber(self:GetCellDt().taskContentNum)) and not self:IsHasDrawn()
end

function BeginnerAssembleWelfareCell:Awake()
	SetButtonAction(self.FontStyleButton, function()
		if self:IsCanDrawn() then
			if type(self.btnActionGet) == 'function' then
				if self:IsCanDrawn() then
					self.btnActionGet(self.cellDt)
				else
					GameUtils.Toast(localize('当前不可领取'))
				end
			end
		elseif self:IsCanJump() then
			if type(self.btnActionJump) == 'function' then
				self.btnActionJump(self.cellDt)
			end
		end
	end)
end

function BeginnerAssembleWelfareCell:FreshBaseUI(data)
	self.cellDt = checkTable(data)
	
	local isHasDrawn = self:IsHasDrawn()
	local isCanDrawn = self:IsCanDrawn()
	local isCanJump  = self:IsCanJump()
	--local isMainTask  = checkNumber(data.isMainTask) == 1
	
	
	CfUtils.FillText(self.TextDescribe, data.desc)
	CfUtils.RefreshCommonGoodsListLight(self.CommonGoodsListLight, parse_rewards(data.rewardId, data.rewardNum))

	self.ProgressBar.value = data.progress / data.taskContentNum
	self.TextProgress.text = string.format("%s/%s", data.progress, data.taskContentNum)
	
	KTool.SetActive(self.FontStyleButton, (isCanJump and not isHasDrawn) or isCanDrawn)
	KTool.SetActive(self.TextUnderWay, not isCanJump and not isHasDrawn and not isCanDrawn)
	KTool.SetActive(self.TextComplete, isHasDrawn)
	KTool.SetActive(self.CanGet, isCanDrawn)
	--KTool.SetActive(self.ImgMainTask, isMainTask)
	if self.UIFX_BeginnerEventDialogContainer then
		KTool.SetActive(self.UIFX_BeginnerEventDialogContainer, not isHasDrawn)
	end
	
	--CfUtils.SetScale(self.controller.gameObject, isMainTask and Vector3(1.05, 1.05, 0) or Vector3.one)
	
	
	if not isHasDrawn then
		if isCanDrawn then
			self.FontStyleButton:ResetFontStyle("B12", localize("领取"))
		elseif isCanJump then
			self.FontStyleButton:ResetFontStyle("B13", localize("前往"))
		end
	end
end

function BeginnerAssembleWelfareCell:OnDestroy()
	self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
	self:Delete()
	self = nil --lua层的gc需要
end

return BeginnerAssembleWelfareCell